import React from 'react';
import { graphql } from 'gatsby';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';

const PostHero = styled.section`
  min-height: 50vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(
      circle at 80% 20%,
      rgba(247, 147, 30, 0.1) 0%,
      transparent 50%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
`;

const PostMeta = styled.div`
  display: flex;
  align-items: center;
  gap: ${props => props.theme.space[4]};
  margin-bottom: ${props => props.theme.space[4]};
  font-size: ${props => props.theme.typography.fontSizes.sm};
  color: var(--color-text-secondary);
`;

const PostDate = styled.time`
  color: ${props => props.theme.colors.primary};
  font-weight: ${props => props.theme.typography.fontWeights.semibold};
`;

const PostTags = styled.div`
  display: flex;
  gap: ${props => props.theme.space[2]};
  flex-wrap: wrap;
`;

const Tag = styled.span`
  padding: ${props => props.theme.space[1]} ${props => props.theme.space[3]};
  background-color: rgba(255, 107, 53, 0.1);
  border: 1px solid ${props => props.theme.colors.primary};
  border-radius: ${props => props.theme.radii.full};
  font-size: ${props => props.theme.typography.fontSizes.xs};
  color: ${props => props.theme.colors.primary};
  font-weight: ${props => props.theme.typography.fontWeights.medium};
`;

const PostTitle = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['5xl']};
  margin-bottom: ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.accent} 0%,
    ${props => props.theme.colors.primary} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['3xl']};
  }
`;

const PostDescription = styled.p`
  font-size: ${props => props.theme.typography.fontSizes.xl};
  color: var(--color-text-secondary);
  max-width: 800px;
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
`;

const PostContent = styled.article`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[12]} ${props => props.theme.space[6]};

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
    margin-top: ${props => props.theme.space[16]};
    margin-bottom: ${props => props.theme.space[6]};
    color: var(--color-text);
  }

  h3 {
    font-size: ${props => props.theme.typography.fontSizes['2xl']};
    margin-top: ${props => props.theme.space[10]};
    margin-bottom: ${props => props.theme.space[4]};
    color: var(--color-text);
  }

  h4 {
    font-size: ${props => props.theme.typography.fontSizes.xl};
    margin-top: ${props => props.theme.space[8]};
    margin-bottom: ${props => props.theme.space[3]};
    color: var(--color-text);
  }

  p {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
  }

  img {
    width: 100%;
    border-radius: ${props => props.theme.radii.xl};
    margin: ${props => props.theme.space[8]} 0;
    box-shadow: ${props => props.theme.shadows.xl};
  }

  ul, ol {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
    padding-left: ${props => props.theme.space[8]};
  }

  li {
    margin-bottom: ${props => props.theme.space[3]};
  }

  blockquote {
    border-left: 4px solid ${props => props.theme.colors.primary};
    padding-left: ${props => props.theme.space[6]};
    margin: ${props => props.theme.space[8]} 0;
    font-style: italic;
    color: var(--color-text-secondary);
    font-size: ${props => props.theme.typography.fontSizes.xl};
  }

  code {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[1]} ${props => props.theme.space[2]};
    border-radius: ${props => props.theme.radii.sm};
    font-family: ${props => props.theme.typography.fonts.mono};
    font-size: 0.9em;
  }

  pre {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[6]};
    border-radius: ${props => props.theme.radii.lg};
    overflow-x: auto;
    margin: ${props => props.theme.space[8]} 0;

    code {
      background: none;
      padding: 0;
    }
  }

  hr {
    margin: ${props => props.theme.space[12]} 0;
    border: none;
    height: 1px;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--color-border) 50%,
      transparent 100%
    );
  }

  /* Math equations */
  .katex-display {
    margin: ${props => props.theme.space[8]} 0;
    overflow-x: auto;
    overflow-y: hidden;
  }

  .katex {
    font-size: 1.1em;
  }
`;

function BlogPost({ data }) {
  const { markdownRemark: post } = data;

  if (!post) {
    return <div>Post not found</div>;
  }

  const { frontmatter, html } = post;

  return (
    <Layout
      title={frontmatter.title}
      description={frontmatter.description}
      path={`/blog/${frontmatter.page_id}`}
    >
      <PostHero>
        <HeroContent>
          <PostMeta>
            {frontmatter.date && (
              <PostDate>{frontmatter.date}</PostDate>
            )}
            {frontmatter.tags && frontmatter.tags.length > 0 && (
              <>
                <span>•</span>
                <PostTags>
                  {frontmatter.tags.map((tag, index) => (
                    <Tag key={index}>{tag}</Tag>
                  ))}
                </PostTags>
              </>
            )}
          </PostMeta>
          <PostTitle>{frontmatter.title}</PostTitle>
          {frontmatter.description && (
            <PostDescription>{frontmatter.description}</PostDescription>
          )}
        </HeroContent>
      </PostHero>

      <PostContent>
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </PostContent>
    </Layout>
  );
}

export default BlogPost;

export const query = graphql`
  query BlogPostByIdAndLanguage($id: String!, $language: String!) {
    markdownRemark(id: { eq: $id }) {
      id
      html
      frontmatter {
        page_id
        title
        description
        date(formatString: "MMMM DD, YYYY")
        tags
        categories
        lang
      }
    }
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
